function bukaWA() {
  const nama = document.getElementById("nama").value.trim();
  const uid = document.getElementById("uid").value.trim() || uidParam;
  if (!nama) { alert("Isi nama kamu dulu!"); return false; }
  if (!uid) { alert("UserId tidak ditemukan."); return false; }
  const pesan = encodeURIComponent(
    "Halo kak, mau beli key NANG RBXM 🙏\\n\\n" +
    "Nama: " + nama + "\\n" +
    "UserId: " + uid + "\\n" +
    "Nominal: Rp500\\n\\n" +
    "Bukti transfer saya lampirkan di bawah."
  );
  window.open("https://wa.me/6281252425581?text=" + pesan, "_blank");
  return false;
}

async function getKey() {
  const uid = document.getElementById("uid").value.trim();
  const e = document.getElementById("err");
  const r = document.getElementById("res");
  e.classList.remove("on"); r.classList.remove("on");
  if (!uid || isNaN(+uid) || +uid < 1) {
    e.textContent = "UserId tidak valid."; e.classList.add("on"); return;
  }
  try {
    const x = await fetch("/api?uid=" + uid);
    const d = await x.json();
    if (!d.ok) { e.textContent = d.error || "Error"; e.classList.add("on"); return; }
    document.getElementById("key").textContent = d.key;
    document.getElementById("exp").textContent = "Expired dalam " + d.exp;
    r.classList.add("on");
  } catch(err) {
    e.textContent = "Gagal hubungi server."; e.classList.add("on");
  }
}

